inline const IconDef& getIcon(uint8_t opcode) {
    return ICONS_TABLE[opcode];
}

inline const IconDef* findIconByName(const std::string& name) {
    for (int i = 0; i < 256; ++i) {
        if (name == ICONS_TABLE[i].name) return &ICONS_TABLE[i];
    }
    return nullptr;
}

inline std::string renderSVG(uint8_t opcode, int size = 24, const std::string& color = "currentColor", double strokeWidth = 2.0, const std::string& extraClass = "") {
    const auto& icon = getIcon(opcode);
    std::stringstream ss;
    ss << "<svg xmlns=\"http://www.w3.org/2000/svg\" "
       << "width=\"" << size << "\" height=\"" << size << "\" "
       << "viewBox=\"0 0 24 24\" "
       << "fill=\"none\" stroke=\"" << color << "\" stroke-width=\"" << strokeWidth << "\" "
       << "stroke-linecap=\"round\" stroke-linejoin=\"round\" "
       << "class=\"danphe-icon danphe-icon-" << (int)opcode;
    if (!extraClass.empty()) ss << " " << extraClass;
    ss << "\">" << icon.elements << "</svg>";
    return ss.str();
}

